-- Prepared only: NOT APPLIED to any remote database by this change. Idempotent.
-- SQL mirror of src/core/text/display-text-rule.ts (single display-text rule):
-- NFC, no leading/trailing whitespace (JS String.prototype.trim set), 1..max code
-- points, no \p{Cc} / \p{Cf} / U+2028 / U+2029 (TAB/LF/CR allowed when multiline).
-- The character classes are generated by toPostgresCharClass() and checked by test.
begin;
create or replace function public.oria_display_text_ok(value text, max_len integer, multiline boolean default false)
returns boolean
language sql immutable parallel safe
set search_path = pg_catalog
as $$
  select value is not null
    and value is nfc normalized
    and char_length(value) between 1 and max_len
    and value !~ '^[\u0009-\u000d\u0020\u00a0\u1680\u2000-\u200a\u2028-\u2029\u202f\u205f\u3000\ufeff]'
    and value !~ '[\u0009-\u000d\u0020\u00a0\u1680\u2000-\u200a\u2028-\u2029\u202f\u205f\u3000\ufeff]$'
    and (case when multiline then regexp_replace(value, '[\t\n\r]', '', 'g') else value end)
        !~ '[\u0001-\u001f\u007f-\u009f\u00ad\u0600-\u0605\u061c\u06dd\u070f\u0890-\u0891\u08e2\u180e\u200b-\u200f\u2028-\u202e\u2060-\u2064\u2066-\u206f\ufeff\ufff9-\ufffb\U000110bd\U000110cd\U00013430-\U0001343f\U0001bca0-\U0001bca3\U0001d173-\U0001d17a\U000e0001\U000e0020-\U000e007f]'
$$;
revoke all on function public.oria_display_text_ok(text, integer, boolean) from public, anon;
grant execute on function public.oria_display_text_ok(text, integer, boolean) to authenticated, service_role;
commit;
